content.text:
        data=b''.join(blocks)
        del blocks
        if capture['encoding']=='zstd':
            data=decompress(data,budget)
        elif len(data)>budget:
            raise CaptureError('plain byte budget')
        budget-=len(data)
        reader=logical_records(data)
        try:
            header=next(reader,None)
            if header!=list(COLUMNS):
                raise CaptureError('invalid CSV header')
            ordinal=0
            for values in reader:
                count+=1
                if count>MAX_RECORDS:
                    raise CaptureError('capture record budget')
                if any(len(v)>MAX_FIELD or
                       (not v.isascii() and len(v.encode('utf-8'))>MAX_FIELD)
                       for v in values):
                    raise CaptureError('capture field budget')
                try:
                    record=parse_record(values,context,lookup)
                except (Invalid,ValueError,TypeError,KeyError,IndexError):
                    rejected.append([number,ordinal])
                else:
                    records.append(record)
                ordinal+=1
        except (UnicodeError,csv.Error) as exc:
            raise CaptureError('invalid capture encoding') from exc
    return records,rejected


def record_response(networks,key,target,responder,same_is_internal=True):
    bucket=networks.setdefault(key,{'network':key,'internal':set(),'external':set()})
    if target==responder:
        if not same_is_internal:
            return None
        role='internal'
    else:
        role='external'
    bucket[role].add(responder)
    return role


def classify(records,leases,at,lookup):
    """Reconcile lease-scoped discovery roles and quarantine state.

    Returns the per lease mapping of the clean internal and external role
    addresses at the given query time.
    """
    from census import lease_states
    from ledger import Ledger
    live,_=Ledger(records).at(at)
    context={'leases':leases,'lookup':lookup}
    return lease_states(live,context,at)


